            _run.Performance.End(SearchMetricPhase.FinalSelection, finalMeasurement);
            _run.WorkPacer.ObserveGcPause();
            stopwatch.Stop();
            long workerAllocatedBytes =
                GC.GetAllocatedBytesForCurrentThread() - allocatedBytesAtStart
