            && parent.Snapshot.StrategyGoalCount == 0 && parent.Snapshot.StrategyGoalHpCredit == 0
            && !ReferenceEquals(FindTurnStart(parent), parent)
            && parent.Cycle is null && parent.CycleProbeLease is null && parent.CycleExitProbe is null
            && parent.CycleExitObservation is null && parent.PendingCycleExitObservation is null
            && parent.OrderedMutationLineage is null && parent.OrderedMutationRetentionLease is null
            && parent.CrossTurnProbe is null && parent.PowerCommitment is null
            && CanUseSharedPotionTier(ExplicitPotionUseCount(parent), _maximumPotionUses,
                _forceAllPotionsDisabled, _potionPolicy, _potionStrategy.HasForcedDirectives);

    // Null is an explicit, proven-losing completed child. All other Replay callers
