    {
        bool eligible = action.Kind == PlanActionKind.EndTurn && CanBoundCompletedEndTurn(parent);
        if (!eligible || _roundReplayCheckpoint is not null || _executionChoiceReplayCheckpoint is not null
            || _cardChoiceReplayCheckpoint is not null || _potionChoiceReplayCheckpoint is not null
            || policy.VerifyIncrementalSearch)
        {
            SimulationSnapshot completed = ReplayAction(parent, action, roundCheckpointCapture: capture);
            // Strict verification compares the full real snapshot before applying
            // the same branch proof; never bypass its original replay audit.
            if (eligible && policy.VerifyIncrementalSearch && capture?.HasCheckpoint != true
                && completed.BoundaryReason == SearchBoundaryReason.None
                && TryPruneCompletedTurnBeforeSnapshot(completed.Simulator))
            {
                completed.ReleaseSimulator();
                return null;
            }
            return completed;
        }
        using ReplayForkSeed? seed = _parallelActionReplayForkGate is null ? null
            : PrepareReplayForkSeed(parent.Snapshot, _parallelActionReplayForkGate);
        return SearchTransitionGuard.Execute(action, parent.StateKey, parent.ActionCount,
            () => ReplayCore([action], parent.Snapshot, parent.Turn, parent.ActionCount,
                replayForkSeed: seed, roundCheckpointCapture: capture, allowCompletedTurnBound: true));
    }

    private bool TryPruneCompletedTurnBeforeSnapshot(CombatPredictionSimulator simulator)
    {
        long started = System.Diagnostics.Stopwatch.GetTimestamp();
        try { return TryPruneCompletedTurnBeforeSnapshotCore(simulator); }
        finally { Interlocked.Add(ref _completedTurnProofCounters.QueryTicks,
            System.Diagnostics.Stopwatch.GetTimestamp() - started); }
    }
    private bool TryPruneCompletedTurnBeforeSnapshotCore(CombatPredictionSimulator simulator)
    {
        Interlocked.Increment(ref _completedTurnProofCounters.Checks);
        var combat = (SimulatedCombatState)simulator.State.CombatState;
        var player = simulator.State.GetCreature(_player.Creature);
        if (!simulator.IsInProgress || simulator.HasPendingChoice || !player.IsAlive
            || combat.DeathSaveUseCount != 0 || combat.GrowthRewards.Total != 0
            || simulator.State.GetPlayerCombatState(_player).Phase != PlayerTurnPhase.Play
            || GetCoverageSummary(simulator).HasUncompensatedRisk)
        {
            Interlocked.Increment(ref _completedTurnProofCounters.Unreliable);
            return false;
        }
        int uses = combat.PotionUses.Count(static use => !use.Automatic);
        var bucket = new PrimaryIncumbentBucket(
            TheftEncounterStrategy.OutstandingStolenResource(simulator, combat), uses);
        if (!_primaryIncumbents.TryGet(bucket, out var incumbent))
        {
            Interlocked.Increment(ref _completedTurnProofCounters.NoWitness);
            return false;
        }
        int healing = StrategicHpRecoveryBound.ComponentHealingUpperBound(simulator, _player,
            root.PostCombatRelicHeal.UnconditionalHeal + root.PostCombatRelicHeal.WoundedHeal,
            includePotionHealing: !_forceAllPotionsDisabled, maximumExplicitPotionUses: _maximumPotionUses,
            potionStrategy: _potionStrategy, effectivePotionPolicy: _potionPolicy, useReviewedSources: true);
        if (healing == int.MaxValue)
        {
            Interlocked.Increment(ref _completedTurnProofCounters.Unknown);
            return false;
        }
        int lower = ActEndingBossPolicy.StrategicHpDeficit(combat.GetCumulativeHpLost(_player.Creature),
            maxHpDeficit: 0, StrategicHpRecoveryBound.OptimisticRecoveredHp(
                combat.GetRecoveredHp(_player.Creature), player.CurrentHp, player.MaxHp, healing),
            _strategicBossHpRelief, combat.DeathSaveRelicHpRestored + combat.DeathSavePotionHpRestored);
        _completedTurnProofObserverForTesting?.Invoke(simulator, lower);
        if (lower <= incumbent.StrategicHpDeficit) return false;
        Interlocked.Increment(ref _completedTurnProofCounters.Avoided);
        _run.PrimaryIncumbentBranchesPruned++;
        return true;
    }

    private void EmitCompletedTurnProofDiagnostics()
    {
        if (root.CanCertifyCompletedTurnHealing)
            policy.Diagnostics.Info($"COMPLETED_TURN_COST worker_sum_ms={_completedTurnProofCounters.QueryTicks * 1000d / System.Diagnostics.Stopwatch.Frequency:R} unknown={_completedTurnProofCounters.Unknown} no_witness={_completedTurnProofCounters.NoWitness} unreliable={_completedTurnProofCounters.Unreliable}");
        if (root.CanCertifyCompletedTurnHealing)
            policy.Diagnostics.Info($"[CombatSolver/Test] COMPLETED_TURN_BOUND "
                + $"checks={_completedTurnProofCounters.Checks} "
                + $"pruned={_completedTurnProofCounters.Avoided}");
    }
}

