        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (var power in live.Creatures.SelectMany(c => c.Powers).ToArray()) await PowerCmd.Remove(power);
        foreach (var potion in player.PotionSlots.ToArray()) potion?.Discard();
        await ClearPlayerPilesAsync(player);
        foreach (string id in new[] { "BLOODLETTING", "BLOODLETTING", "STRIKE_IRONCLAD",
                     "STRIKE_IRONCLAD", "STRIKE_IRONCLAD", "STORM_OF_STEEL" })
            await InjectCardAsync(live, player, new() { CardId = id, Pile = "Hand" });
        await CreatureCmd.SetMaxHp(player.Creature, 80);
        await CreatureCmd.SetCurrentHp(player.Creature, 80);
        await CreatureCmd.SetMaxHp(live.Enemies.Single(), 18);
        await CreatureCmd.SetCurrentHp(live.Enemies.Single(), 18);
        await SetBlockAsync(player.Creature, 0);
        SetEnergy(player, 0);
        await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), live.Enemies.Single(),
            5, live.Enemies.Single(), null);
        if (regen)
            await PowerCmd.Apply<RegenPower>(new ThrowingPlayerChoiceContext(), player.Creature,
                6, player.Creature, null);
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        if (!root.CanCertifyCompletedTurnHealing || root.UsesComponentHealingCertificate)
            throw new InvalidOperationException("Independent proof qualification failed: "
                + root.CompletedTurnHealingRejection + "/" + root.ComponentHealingRejection);
        var policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null) with
        {
            FixedBudget = true, VerifyIncrementalSearch = true, MaxDegreeOfParallelism = 2,
            DetailedDiagnostics = false, MeasurePhasePerformance = false,
            BudgetOverrideMilliseconds = null, StopAtAcceptableBattleHpLoss = false,
            PotionPolicy = SolverPotionPolicy.Disabled,
            PotionStrategy = new(SolverPotionPolicy.Disabled, []), RelicTargets = [],
            DisableSharedPrimaryIncumbentsForTesting = false, PrimaryIncumbents = new(),
        };
        policy = policy with { Profile = policy.Profile with
            { BeamWidth = 8, MaxExpandedNodes = 200, SoftTimeBudgetMilliseconds = 10000 } };
        var parent = root.ForkSimulator();
        string parentBefore = DescribeContinuationContractState(parent, root, player);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        Directory.CreateDirectory(_request.EvidenceDirectory!);
        void Mark(string value)
            => File.AppendAllText(Path.Combine(_request.EvidenceDirectory!, "fixture-progress.txt"),
                DateTime.UtcNow.ToString("O") + " " + value + Environment.NewLine);
        Mark("root-qualified");
        var names = SolverDisplayNames.Capture(live);
        var damage = BattleDamageTracker.Observe(live);
        Mark("main-thread-input-captured");
        var result = await Task.Run(() => CombatBeamSolver.CompletedFixtureForTesting(root,
            names, damage, policy, regen, Mark)).WaitAsync(TimeSpan.FromSeconds(20));
        Mark("proof-completed");
        if (DescribeContinuationContractState(parent, root, player) != parentBefore
            || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Proof mutated parent, native state or RNG.");
        using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(20));
        foreach (var node in result.Prefix)
        {
            Mark("native-play-" + node.Action!.CardId);
            var native = player.PlayerCombatState!.Hand.Cards.First(card => card.Id.Entry == node.Action!.CardId);
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                queued => queued is PlayCardAction play
                    && ReferenceEquals(play.NetCombatCard.ToCardModelOrNull(), native),
                () => { if (!native.TryManualPlay(native.TargetType == TargetType.AnyEnemy
                    ? live.Enemies.Single() : null)) throw new InvalidOperationException("Native play refused."); },
                deadline.Token);
            await action.CompletionTask.WaitAsync(deadline.Token);
            var expected = ContinuationStamp.CapturePredicted(player, node.Snapshot.Simulator,
                node.Turn, root.Forecast, root.StartTurnNumber);
            var actual = ContinuationStamp.CaptureLive(live);
            if (actual.StateText != expected.StateText)
                throw new InvalidOperationException("Native prefix differs after " + node.Action!.CardId + ": "
                    + string.Join("; ", expected.DescribeDifferences(actual, 8)));
        }
        string laterBefore = ContinuationStamp.CapturePredicted(player, result.Later.Simulator,
            result.Later.Turn, root.Forecast, root.StartTurnNumber).StateText;
        CombatPredictionSimulator[] forks;
        using (SimulationNotificationIsolation.Enter())
            forks = Enumerable.Range(0, 16).Select(_ => result.Later.Simulator.Fork()).ToArray();
        await Task.WhenAll(forks.Select(child => Task.Run(() =>
        {
            using var isolation = SimulationNotificationIsolation.Enter();
            if (ContinuationStamp.CapturePredicted(player, child, result.Later.Turn,
                    root.Forecast, root.StartTurnNumber).StateText != laterBefore)
                throw new InvalidOperationException("Owned parallel Fork differs.");
            child.State.GetCreature(player.Creature).CurrentHp--;
        })));
        if (ContinuationStamp.CapturePredicted(player, result.Later.Simulator,
                result.Later.Turn, root.Forecast, root.StartTurnNumber).StateText != laterBefore)
            throw new InvalidOperationException("Fork changed its parent.");
        int previous = player.PlayerCombatState!.TurnNumber;
        Mark("native-end-turn");
        CombatManager.Instance.OnEndedTurnLocally();
        var end = new EndPlayerTurnAction(player, previous);
        RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue(end);
        await end.CompletionTask.WaitAsync(deadline.Token);
        while (player.PlayerCombatState is not { Phase: PlayerTurnPhase.Play } current
               || current.TurnNumber <= previous)
        {
            deadline.Token.ThrowIfCancellationRequested(); EnsureWithinDeadline(); await NextFrameAsync();
        }
        var finalActual = ContinuationStamp.CaptureLive(live);
        var finalExpected = ContinuationStamp.CapturePredicted(player, result.Later.Simulator,
            result.Later.Turn, root.Forecast, root.StartTurnNumber);
        if (finalActual.StateText != finalExpected.StateText)
            throw new InvalidOperationException("Full native EndTurn differs: "
                + string.Join("; ", finalExpected.DescribeDifferences(finalActual, 8)));
        await InjectCardAsync(live, player, new() { CardId = "FEED", Pile = "Exhaust", TreatAsDeckCard = true });
        if (CombatRootSnapshot.Capture(live).CanCertifyCompletedTurnHealing
            || DescribeContinuationContractState(parent, root, player) != parentBefore)
            throw new InvalidOperationException("Unknown initial exhausted source or immutable root failed.");
        _completedChecks.Add($"CompletedTurn:IndependentQualification:ActualCompleteP0Witness:Pruned={result.Pruned}:ActiveRegen={regen}:RawStateAndLowerBoundMatch:StrictFullReplay:16ActualEndTurnWorkers:ActualEqualHpWitnessKept:TurnStartBaselineAndUnknownRefused:SixNativeCardsAndFullEndTurn:ParentLiveRngIsolation");
        result.Later.ReleaseSimulator();
        foreach (var node in result.Prefix) node.Snapshot.ReleaseSimulator();
    }
}

internal sealed partial class CombatBeamSolver
{
    internal sealed record CompletedFixtureResult(IReadOnlyList<SearchNode> Prefix, SimulationSnapshot Later, int Pruned);

    internal static CompletedFixtureResult CompletedFixtureForTesting(CombatRootSnapshot root,
        SolverDisplayNames names, BattleDamageSnapshot damage, SearchPolicySnapshot policy, bool regen,
        Action<string> mark)
    {
        using var isolation = SimulationNotificationIsolation.Enter();
        using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(20));
        var solver = new CombatBeamSolver(root, names, damage, policy, deadline.Token, maximumPotionUses: 0);
        mark("solver-created");
        SearchNode opening = CreateOpeningSearchSeed(solver.Replay([]));
        mark("opening-replayed");
        SearchNode Play(SearchNode parent, string id) => solver.CostChildForTesting(parent,
            solver.PrepareCardActions(parent).First(a => a.Action.CardId == id).Action);
        if (solver.CanBoundCompletedEndTurn(opening))
            throw new InvalidOperationException("Turn-start stand-pat baseline was not preserved.");
        SearchNode winner = opening;
        foreach (string id in new[] { "BLOODLETTING", "BLOODLETTING", "STRIKE_IRONCLAD",
                     "STRIKE_IRONCLAD", "STRIKE_IRONCLAD" })
        {
            mark("witness-play-" + id);
            winner = Play(winner, id);
        }
        if (!winner.IsTerminal || winner.Snapshot.HasRisk || winner.Snapshot.PlayerDead
            || !solver.TightenPrimarySearchIncumbentAtTurnLayer([winner], 0)
            || !solver._primaryIncumbents.TryGet(new(0, 0), out var incumbent))
            throw new InvalidOperationException("Actual complete policy witness was not published.");
        mark("complete-witness");
        List<SearchNode> prefix = [];
        SearchNode bad = opening;
        foreach (string id in new[] { "BLOODLETTING", "STORM_OF_STEEL", "SHIV", "SHIV", "SHIV", "SHIV" })
            prefix.Add(bad = Play(bad, id));
        if (!solver.CanBoundCompletedEndTurn(bad) || bad.IsTerminal || bad.Snapshot.HasRisk)
            throw new InvalidOperationException("Completed-turn fixture was not eligible.");
        mark("bad-prefix");
        var end = new PlanAction(PlanActionKind.EndTurn, bad.Turn);
        SimulationSnapshot later = solver.ReplayAction(bad, end);
        if (later.BoundaryReason != SearchBoundaryReason.None || later.HasRisk
            || later.AllEnemiesDead || later.PlayerDead)
            throw new InvalidOperationException("Reference EndTurn is not reliable and complete.");
        string expected = ContinuationStamp.CapturePredicted(root.PlayerIdentity, later.Simulator,
            later.Turn, root.Forecast, root.StartTurnNumber).StateText;
        int healing = StrategicHpRecoveryBound.ComponentHealingUpperBound(later.Simulator,
            root.PlayerIdentity, 0, includePotionHealing: false, maximumExplicitPotionUses: 0,
            useReviewedSources: true);
        int expectedLower = StrategicHpLowerBound(later, solver._strategicBossHpRelief, healing);
        Action<CombatPredictionSimulator, int> observe = (sim, lower) =>
        {
            if (ContinuationStamp.CapturePredicted(root.PlayerIdentity, sim,
                    ((SimulatedCombatState)sim.State.CombatState).GetPlayerTurnNumber(root.PlayerIdentity),
                    root.Forecast, root.StartTurnNumber).StateText != expected || lower != expectedLower)
                throw new InvalidOperationException("Raw completed state or HP lower bound differed from full snapshot.");
        };
        solver._completedTurnProofObserverForTesting = observe;
        var strict = solver.ReplayCompletedEndTurn(bad, end);
        if ((strict is not null) != regen)
            throw new InvalidOperationException("Strict full audit did not preserve the expected disposition.");
        strict?.ReleaseSimulator();
        var raw = new CombatBeamSolver(root, names, damage, policy with { VerifyIncrementalSearch = false },
            deadline.Token, maximumPotionUses: 0) { _completedTurnProofObserverForTesting = observe };
        var child = raw.ReplayCompletedEndTurn(bad, end);
        if ((child is not null) != regen)
            throw new InvalidOperationException("Pre-snapshot actual proof did not prune/retain its child.");
        child?.ReleaseSimulator();
        mark("raw-and-strict-dispositions");
        // Seed each worker from a separately owned parent before any concurrent Fork.
        var owned = Enumerable.Range(0, 16).Select(_ => solver.Snapshot(bad.Snapshot.Simulator.Fork(),
            bad.Turn, bad.ActionCount, bad.Snapshot.ShufflesCrossed, SearchBoundaryReason.None,
            new ForkableSet<uint>())).ToArray();
        SearchNode Node(SimulationSnapshot snapshot) => new(bad.Action, bad.ActionCount,
            snapshot.PotionUseCount, snapshot.PotionStrategicCost, snapshot.Turn, bad.Traits,
            bad.FutureSoldHp, snapshot.Score, snapshot.StateKey, snapshot.HasRisk,
            snapshot.BoundaryReason, false, bad.Parent, snapshot, CombatProgressState.Capture(snapshot));
        var workers = Enumerable.Range(0, 16).Select(_ => raw.CreateExpansionWorker()).ToArray();
        Parallel.For(0, 16, i =>
        {
            using var workerIsolation = SimulationNotificationIsolation.Enter();
            workers[i]._completedTurnProofObserverForTesting = observe;
            var completed = workers[i].EvaluatePreparedEndTurn(Node(owned[i]), new object());
            using var batch = completed.Batch ?? throw new InvalidOperationException("Prepared round batch missing.");
            if (completed.Frontier is not null || batch.EndTurns.Count != (regen ? 1 : 0))
                throw new InvalidOperationException("Actual parallel round worker returned an invalid disposition.");
            owned[i].ReleaseSimulator();
        });
        if (raw._completedTurnProofCounters.Avoided != (regen ? 0 : 17))
            throw new InvalidOperationException("Shared actual worker pruning count differed.");
        mark("sixteen-actual-round-workers");
        // Equality uses another actual completed victory, not a filled-in bound.
        if (!regen)
        {
            var equalPolicy = policy with { PrimaryIncumbents = new(), VerifyIncrementalSearch = false };
            var equal = new CombatBeamSolver(root, names, damage, equalPolicy, deadline.Token, maximumPotionUses: 0);
            var advanced = solver.CostChildForTesting(bad, end);
            var equalityWinner = solver.CostChildForTesting(advanced,
                solver.PrepareCardActions(advanced).First(a => a.Action.CardId == "STRIKE_IRONCLAD").Action);
            if (!equalityWinner.IsTerminal || !equal.TightenPrimarySearchIncumbentAtTurnLayer([equalityWinner], 0)
                || !equal._primaryIncumbents.TryGet(new(0, 0), out var equalWitness)
                || equalWitness.StrategicHpDeficit != expectedLower
                || equal.ReplayCompletedEndTurn(bad, end) is not { } kept)
                throw new InvalidOperationException("Actual equal-HP complete witness did not retain equality.");
            kept.ReleaseSimulator();
        }
        var unknownSimulator = bad.Snapshot.Simulator.Fork();
        unknownSimulator.AddGeneratedCardToCombat(PredictedCard.Create(ModelDb.Card<Feed>(), root.PlayerIdentity),
            PileType.Exhaust, root.PlayerIdentity, resultKind: CardGenerationResultKind.Fixed);
        var unknown = solver.Snapshot(unknownSimulator, bad.Turn, bad.ActionCount,
            bad.Snapshot.ShufflesCrossed, SearchBoundaryReason.None, new ForkableSet<uint>());
        var keptUnknown = raw.ReplayCompletedEndTurn(Node(unknown), end);
        if (keptUnknown is null) throw new InvalidOperationException("Unknown exhausted branch source was pruned.");
        keptUnknown.ReleaseSimulator(); unknown.ReleaseSimulator();
        mark("actual-equality-and-unknown");
        foreach (var guarded in new[]
        {
            policy with { TheftPolicy = SolverTheftPolicy.PreserveResources },
            policy with { GrowthOpportunityTargets = GrowthOpportunityTargets.UnboundedForTesting("completed-turn") },
            policy with { RelicTargets = [new(RelicCounterId.PenNib, 2, 2, 0, 10)] },
            policy with { PotionStrategy = new(SolverPotionPolicy.Disabled,
                [new(0, "ENERGY_POTION", SolverPotionDirective.Force)]) },
        })
            if (new CombatBeamSolver(root, names, damage, guarded, deadline.Token, maximumPotionUses: 0)
                .CanBoundCompletedEndTurn(bad))
                throw new InvalidOperationException("Policy/resource guard admitted early snapshot pruning.");
        opening.Snapshot.ReleaseSimulator();
        return new(prefix, later, regen ? 0 : 1);
    }
}

